let state={answers:{},read:[],known:[],drafts:{},checks:{}},storageOK=true;
try{const v=JSON.parse(localStorage.getItem('english-studio-v1')||'null');if(v&&typeof v==='object')state={...state,...v};if(!state.answers||Array.isArray(state.answers))state.answers={};for(const k of ['read','known'])if(!Array.isArray(state[k]))state[k]=[];}catch{storageOK=false}
let session=null,orderSelection=[],flashOpen=new Set(),vocabGroup='All',search='',writingType='profile';
const iconPaths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M12 6c-3-2-6-2-10-1v15c4-1 7-1 10 1m0-15c3-2 6-2 10-1v15c-4-1-7-1-10 1V6Z',practice:'m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15v5Z',words:'M4 5h9M8 3v2c0 7-3 10-6 12m2-8c2 4 5 6 9 7m1 5 5-13 5 13m-8-4h7',writing:'M5 3h10l4 4v14H5V3Zm9 0v5h5M8 12h8m-8 4h6',review:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2',arrow:'M5 12h14m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',more:'M5 12h.01M12 12h.01M19 12h.01',close:'m6 6 12 12M6 18 18 6',folder:'M3 7V5h7l2 3h9v12H3V7Z',calendar:'M4 5h16v16H4V5Zm4-3v6m8-6v6M4 11h16',audio:'M4 9h4l5-5v16l-5-5H4V9Zm12-2c3 3 3 7 0 10m3-13c5 5 5 11 0 16',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.book}"/></svg>`}
function lessonProgress(l){const qs=D.questions.filter(q=>q.topic===l.id),done=qs.filter(q=>state.answers[q.id]?.correct).length;return {total:qs.length,done,pct:Math.round(done/qs.length*100)}}
function save(){try{localStorage.setItem('english-studio-v1',JSON.stringify(state))}catch{storageOK=false}$('#save-status').textContent=storageOK?'Guardado en este navegador':'Guardado solo en esta sesión';$('#error-count').textContent=missed().length;const rail=document.querySelector('#rail-progress');if(rail){rail.textContent=state.read.length+' de 8 bloques';document.querySelector('#rail-progress-bar').style.width=(state.read.length/8*100)+'%';}}
function toast(s){$('#toast').textContent=s;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',4200)}
function stats(){let a=Object.values(state.answers),tries=a.reduce((s,x)=>s+x.attempts,0),right=a.reduce((s,x)=>s+x.correctAttempts,0);return{done:a.length,tries,right,accuracy:tries?Math.round(right/tries*100):0,mastered:a.filter(x=>x.correct).length}}
function missed(){return D.questions.filter(q=>state.answers[q.id]&&!state.answers[q.id].correct)}
function btn(text,href,secondary=false){return `<a class="btn ${secondary?'secondary':''}" href="${href}">${text}<span aria-hidden="true">↗</span></a>`}
function heading(k,h,p){return `<div class="page-head"><div class="eyebrow">${k}</div><h1>${h}</h1><p>${p}</p></div>`}
function home(){const s=stats(),next=D.lessons.find(l=>!state.read.includes(l.id))||D.lessons[0],n=D.lessons.indexOf(next)+1,percent=Math.round(state.read.length/D.lessons.length*100);return `<div class="dashboard-intro"><div><span class="overline">Tu inglés, un día a la vez</span><h1>Hola, Luis<span class="greeting-dot">.</span></h1><p>Un buen momento para seguir aprendiendo.</p></div><a class="text-link" href="#plan">${icon('calendar')} Ver mi plan de estudio</a></div><div class="dashboard-top"><section class="continue-card"><div class="continue-copy"><div class="course-chip">Unidad 1 <span>·</span> Identity & personality</div><h2>Tu siguiente paso:<br><em>${next.subtitle}</em></h2><p lang="en">${next.desc}</p><div class="actions">${btn(state.read.length?'Continuar estudiando':'Comenzar la unidad','#guide/'+next.id)}<span class="lesson-ref">Bloque ${n} de 8</span></div></div><div class="unit-art" aria-hidden="true"><span class="art-label">ENGLISH / C1</span><span class="art-one">01</span><div class="art-line"></div><span class="art-caption">A little practice.<br>A story of your own.</span></div></section><section class="unit-progress" aria-labelledby="progress-title"><div class="section-kicker">A tu ritmo</div><h2 id="progress-title">Tu progreso</h2><div class="progress-ring" style="--value:${percent}%"><span><b>${percent}%</b><small>de la guía</small></span></div><div class="progress-caption"><strong>${state.read.length} de 8 bloques</strong><span>marcados como estudiados</span></div><a href="#review" class="text-link">Ver mi actividad ${icon('arrow')}</a></section></div><div class="metric-row"><div>${icon('practice')}<span><b>${s.done}<small> / 108</small></b><span>Ejercicios practicados</span></span></div><div>${icon('check')}<span><b>${s.tries?s.accuracy+'%':'—'}</b><span>Acierto en tus intentos</span></span></div><div>${icon('words')}<span><b>${state.known.length}<small> / 70</small></b><span>Expresiones aprendidas</span></span></div></div><div class="home-grid"><section><div class="section-title"><div><span class="section-kicker">Explora la unidad</span><h2>Tu ruta de aprendizaje</h2></div><span>8 bloques</span></div><div class="lesson-list">${D.lessons.map(l=>{const lp=lessonProgress(l),read=state.read.includes(l.id),current=l.id===next.id;return `<a class="lesson-row ${current?'is-next':''} ${read?'is-read':''}" href="#guide/${l.id}"><span class="lesson-num">${read?icon('check'):l.num}</span><div class="lesson-info"><div class="lesson-title"><h3>${l.subtitle}</h3>${current?'<span class="next-badge">Siguiente</span>':read?'<span class="read-badge">Estudiado</span>':''}</div><p>${l.title}</p></div><span class="lesson-completion"><span>${lp.done}/${lp.total}</span><span class="mini-track"><i style="width:${lp.pct}%"></i></span></span><span class="lesson-arrow">${icon('arrow')}</span></a>`}).join('')}</div></section><aside class="home-aside"><div class="aside-card practice-invite"><span class="aside-symbol">${icon('practice')}</span><span class="section-kicker">Pasa a la acción</span><h3>10 preguntas.<br>Una idea más clara.</h3><p>Mezcla los temas de la unidad y descubre qué necesitas reforzar.</p>${btn('Iniciar práctica rápida','#practice/mixed')}</div><div class="aside-card daily-word"><div class="section-title"><span class="section-kicker">Vocabulario en contexto</span>${icon('words')}</div><h3 class="word" lang="en">a dark horse</h3><p>Alguien que sorprende con un talento inesperado.</p><blockquote lang="en">“I had no idea she played the piano. She’s a dark horse!”</blockquote><a href="#vocab" class="text-link">Explorar las 70 fichas ${icon('arrow')}</a></div>${missed().length?`<a href="#review" class="review-callout">${icon('review')}<span><strong>${missed().length} errores para repasar</strong><small>Una nueva oportunidad de aprender</small></span>${icon('arrow')}</a>`:''}</aside></div>`}
function inline(s){return esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\([^)]+\)/g,'$1')}
function markdown(text){const depths=[...text.matchAll(/^(#+) /gm)].map(m=>m[1].length),baseDepth=Math.min(...depths,4);let lines=text.split('\n'),out='',table=[],list=false,lastHeading=1;function close(){if(table.length){const cells=table.filter(l=>!/^\|[\s:|\-]+\|?$/.test(l));out+='<div class="table-wrap"><table>'+cells.map((l,i)=>'<tr>'+l.split('|').slice(1,-1).map(c=>`<${i?'td':'th'}>${inline(c.trim())}</${i?'td':'th'}>`).join('')+'</tr>').join('')+'</table></div>';table=[]}if(list){out+='</ul>';list=false}}
for(let l of lines){if(l.startsWith('|')){table.push(l);continue}if(/^[-\d]/.test(l)&&/^(?:- |\d+\. )/.test(l)){if(table.length)close();if(!list){out+='<ul>';list=true}out+='<li>'+inline(l.replace(/^(?:- |\d+\. )/,''))+'</li>';continue}close();let h=l.match(/^(#{1,4}) (.+)/);if(h){let n=Math.min(h[1].length-baseDepth+2,4,lastHeading+1);lastHeading=n;out+=`<h${n}>${inline(h[2])}</h${n}>`}else if(l.trim())out+='<p>'+inline(l.replace(/^> /,''))+'</p>'}close();return out}
const guideParts={start:()=>D.resources.extra.split('# Reading and evidence')[0],names:()=>D.resources.guide.split('## 1.1')[1].split('### Grammar:')[0].replace(/^ What’s in a name\?/, '# What’s in a name?')+'\n## Reading and evidence\n'+D.resources.extra.split('# Reading and evidence')[1].split('# Personality')[0],continuous:()=> '# The continuous aspect\n\n### Grammar:'+D.resources.guide.split('### Grammar:')[1].split('## 1.2')[0]+'\n## Lookback contrasts\nShe is coming tomorrow: an arrangement. She comes from Osaka: origin. The house was being painted: passive work in progress. I had been working for sixteen hours: duration before a past event. I have had ten days off: a period up to now. I have been having tennis lessons: repeated activity.\n## A useful reminder\nBoth I have lived here for ten years and I have been living here for ten years can be natural. The continuous highlights duration. Follow the context; a single verb can have more than one valid form.',habits:()=> '# What are you like?\n'+D.resources.guide.split('## 1.2 What are you like?')[1].split('## 1.3')[0]+'\n## Lookback vocabulary\nMature: able to disagree respectfully. Perceptive: notices details. Obstinate: refuses to change. Conscientious: responsible and careful. Open-minded: considers alternatives. Inquisitive: curious.\n## Profiles as discussion\n'+D.resources.extra.split('# Personality and habits')[1].split('# Francesco')[0]+'\n## More idioms\n'+idiomGuide(),pictures:()=> '# Picture perfect\n'+D.resources.guide.split('## 1.3 Picture perfect')[1].split('### Vague language')[0],vague:()=> '# Vague language\n'+D.resources.guide.split('### Vague language in conversation')[1].split('## 1.4')[0]+'\n## Patterns to remember\nA couple of + plural noun. Plenty of + noun, without a. Stuff is uncountable: a lot of stuff; pick it up. Around fifty = fifty or so. Sort of and kind of soften a description. Avoid exactly eight-ish.\n## Example\nWe have a couple of things to do, but plenty of time. Let’s meet at about eight. I’ve left some stuff at the hotel; I’ll collect it later.',objects:()=> '# The stories we keep\n'+D.resources.guide.split('## 1.4 Francesco’s Venice')[1].split('## Writing:')[0]+'\n## Francesco’s Venice\n'+D.resources.extra.split('# Francesco’s Venice')[1].split('# Sound')[0],writing:()=> '# Your story, in words\n'+D.resources.guide.split('## Writing:')[1]+'\n## Speaking practice\n'+D.resources.extra.split('# Sound and speaking')[1]};
function idiomGuide(){return D.vocab.filter(x=>x.group==='Idioms').map(x=>`- **${x.term}**: ${x.meaning}. ${x.example}`).join('\n')}
function guide(id='start'){const l=D.lessons.find(l=>l.id===id)||D.lessons[0],idx=D.lessons.indexOf(l),read=state.read.includes(l.id);return heading('Guía de estudio · Bloque '+(idx+1)+' de 8',l.subtitle,l.desc)+`<div class="mobile-lesson-picker"><label for="lesson-picker">Cambiar de bloque</label><select id="lesson-picker" name="lesson-picker">${D.lessons.map(x=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>${x.num} · ${x.subtitle}</option>`).join('')}</select></div><div class="study-layout"><nav class="toc" aria-label="Bloques de estudio"><div class="toc-title">Contenido de la unidad</div>${D.lessons.map(x=>`<a href="#guide/${x.id}" class="${l.id===x.id?'active':''}" ${l.id===x.id?'aria-current="page"':''}><span class="toc-num">${state.read.includes(x.id)?'✓':x.num}</span>${x.subtitle}</a>`).join('')}<a href="#sources" class="toc-resources">${icon('folder')} Material y solucionarios</a></nav><div class="lesson-content"><div class="reader-toolbar"><span>${l.ref}</span><span class="${read?'status-done':'status-pending'}">${read?'✓ Estudiado':'Por estudiar'}</span></div><article class="reader" lang="en">${markdown(guideParts[l.id]().replace(/^# [^\n]+\n/,''))}<div class="note" lang="es">${icon('book')}<span>Estudia la teoría en inglés y recibe las explicaciones de la práctica en español. El vocabulario incluye traducción y ejemplos.</span></div><div class="reader-actions" lang="es"><button class="btn ${read?'secondary':''}" data-action="read" data-id="${l.id}">${icon('check')}${read?'Bloque estudiado':'Marcar como estudiado'}</button>${btn('Practicar este bloque','#practice/'+l.id,true)}</div></article><nav class="lesson-pagination" aria-label="Lecciones anterior y siguiente">${idx>0?`<a href="#guide/${D.lessons[idx-1].id}"><small>Anterior</small>${D.lessons[idx-1].subtitle}</a>`:'<span></span>'}${idx<7?`<a href="#guide/${D.lessons[idx+1].id}"><small>Siguiente ${icon('arrow')}</small>${D.lessons[idx+1].subtitle}</a>`:`<a href="#practice/mixed"><small>Terminar con práctica</small>Repasar toda la unidad</a>`}</nav></div></div>`}
const typeNames={choice:'Elige la respuesta',gap:'Completa el espacio',error:'Encuentra y corrige el error',order:'Ordena la oración',classify:'Identifica la categoría'};
function shuffle(a){return a.map(v=>({v,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.v)}
function startSession(topic='all',type='all'){let qs=topic==='errors'?missed():D.questions.filter(q=>(topic==='all'||topic==='mixed'||q.topic===topic)&&(type==='all'||q.type===type));qs=shuffle(qs.filter(q=>type==='all'||q.type===type));if(topic==='mixed')qs=qs.slice(0,10);session={topic,type,qs,index:0,checked:false,correct:0,first:true};orderSelection=[];}
function practice(topic='all'){if(!session||session.topic!==topic)startSession(topic);const q=session.qs[session.index];const head=heading(topic==='errors'?'Repaso de errores':'Práctica interactiva',topic==='errors'?'Los errores también enseñan.':'Pon a prueba lo aprendido.','Responde a tu ritmo. Cada intento viene con una explicación para ayudarte a avanzar.');const filters=`<div class="filter-control practice-filters"><div><label for="topic">Tema</label><select id="topic" name="topic">${[['all','Toda la unidad'],['mixed','Sesión mixta · 10 preguntas'],...D.lessons.map(x=>[x.id,x.subtitle]),['errors','Solo errores']].map(([v,n])=>`<option value="${v}" ${v===topic?'selected':''}>${n}</option>`).join('')}</select></div><div><label for="exercise-type">Tipo de ejercicio</label><select id="exercise-type" name="exercise-type"><option value="all">Todos los tipos</option>${Object.entries(typeNames).map(([k,v])=>`<option value="${k}" ${session.type===k?'selected':''}>${v}</option>`).join('')}</select></div><button class="btn secondary" data-action="restart">${icon('review')} Nueva sesión</button></div>`;
if(!session.qs.length)return head+filters+`<div class="empty" style="margin-top:24px"><h2>No hay ejercicios pendientes aquí.</h2><p>Prueba otro tema o tipo de ejercicio. Los fallos aparecerán en el repaso hasta que los resuelvas.</p></div>`;
if(!q)return head+`<div class="empty"><div class="eyebrow">SESIÓN COMPLETADA</div><h2>${session.correct} de ${session.qs.length} respuestas correctas</h2><p>Este resultado corresponde a tu primer intento en cada pregunta de esta sesión. Revisa los errores para afianzar lo aprendido.</p><div class="actions"><button class="btn" data-action="restart">Otra sesión</button>${btn('Repasar errores','#review',true)}</div></div>`;
if(!q._options)q._options=shuffle(q.options||[]);
return head+filters+`<div class="practice-layout"><div><div class="session-heading"><span>Pregunta <strong>${session.index+1}</strong> de ${session.qs.length}</span><span>${session.correct} ${session.correct===1?'correcta':'correctas'} en esta sesión</span></div><section class="question-card" aria-labelledby="question-title"><div class="question-meta"><span>${typeNames[q.type]}</span><span class="topic-tag">${D.lessons.find(l=>l.id===q.topic).subtitle}</span></div><div class="progress" style="margin-bottom:25px"><span style="width:${session.index/session.qs.length*100}%"></span></div><h2 id="question-title" lang="${['names','objects'].includes(q.topic)?'es':'en'}">${esc(q.prompt)}</h2><form id="exercise-form">${['choice','classify'].includes(q.type)?`<fieldset style="border:0;padding:0;margin:0"><legend class="muted" style="font-size:12px">Selecciona una opción</legend><div class="options">${q._options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${esc(o)}" required><span><span class="option-letter" aria-hidden="true">${String.fromCharCode(65+i)}</span>${esc(o)}</span></label>`).join('')}</div></fieldset>`:q.type==='order'?`<label>Tu oración · pulsa una palabra para devolverla</label><div id="answer-zone" class="tokens answer-zone"></div><label>Palabras disponibles</label><div id="word-bank" class="tokens">${q._options.map((w,i)=>`<button type="button" class="token" data-action="word" data-index="${i}">${esc(w)}</button>`).join('')}</div>`:`<label for="answer">${q.type==='error'?'Escribe la oración completa corregida':'Escribe solo lo que falta'}</label><input class="answer-input" id="answer" name="answer" autocomplete="off" autocapitalize="off" spellcheck="false" required placeholder="Tu respuesta…">`}<div id="feedback" aria-live="polite"></div><div class="question-foot"><button class="btn" id="check-btn" type="submit">Comprobar respuesta <span aria-hidden="true">→</span></button><button class="btn secondary" type="button" data-action="hint">${icon('spark')} Pista</button><button class="btn secondary" type="button" data-action="solution">Consultar solución</button><span class="counter">${session.index+1} / ${session.qs.length}</span></div></form></section><p class="correction-note">La corrección escrita compara formas previstas, ignora mayúsculas y puntuación y reconoce contracciones comunes. En frases abiertas puede haber otras respuestas válidas.</p></div><aside class="practice-aside"><div class="coach-card"><span class="aside-symbol">${icon('spark')}</span><h3>Aprender está en el porqué.</h3><ol><li>Intenta resolverlo sin apuntes.</li><li>Si dudas, pide una pista.</li><li>Lee la explicación y crea tu propio ejemplo.</li></ol><a class="text-link" href="#guide/${q.topic}">Consultar este tema ${icon('arrow')}</a></div><div class="session-note">${icon('review')}<p>Tus errores se guardan para volver a practicarlos cuando quieras.</p></div><a href="#review" class="text-link">Ir a mi repaso ${icon('arrow')}</a></aside></div>`}
function normalize(s){return String(s).toLowerCase().replace(/[’‘]/g,"'").replace(/\bi'm\b/g,'i am').replace(/\bit's\b/g,'it is').replace(/\bwe've\b/g,'we have').replace(/\bi've\b/g,'i have').replace(/\bshe's\b/g,'she is').replace(/\bhe's\b/g,'he is').replace(/\bdon't\b/g,'do not').replace(/\bhaven't\b/g,'have not').replace(/\bisn't\b/g,'is not').replace(/\bcan't\b/g,'cannot').replace(/[.,!?;:"']/g,'').replace(/\s+/g,' ').trim()}
function judge(q,a){return (Array.isArray(q.answer)?q.answer:[q.answer]).some(x=>normalize(x)===normalize(a))}
function check(e){e.preventDefault();if(session.checked){next();return}const q=session.qs[session.index];let answer=q.type==='order'?orderSelection.map(i=>q._options[i]).join(' '):new FormData(e.target).get('answer');if(!String(answer||'').trim()){toast('Escribe o selecciona una respuesta primero.');return}const correct=judge(q,answer);const old=state.answers[q.id]||{attempts:0,correctAttempts:0};state.answers[q.id]={correct,attempts:old.attempts+1,correctAttempts:old.correctAttempts+(correct?1:0),last:answer};save();if(correct)session.correct++;session.checked=true;document.querySelectorAll('[data-action=hint],[data-action=solution]').forEach(b=>b.disabled=true);$('#feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}"><strong>${correct?'✓ Correcto. Bien razonado.':q.type==='error'?'Revisa la corrección modelo.':'Todavía no. Fíjate en esta idea.'}</strong>${correct?'':`<p><b>Respuesta esperada:</b> <span lang="en">${esc(q.answer)}</span></p>`}<p>${esc(q.why)}</p>${!correct&&q.type==='error'?'<p style="font-size:12px">Si tu reformulación también es válida, compárala con el modelo; esta revisión no interpreta cualquier paráfrasis.</p>':''}</div>`;$('#check-btn').innerHTML=session.index===session.qs.length-1?'Ver resultado →':'Siguiente pregunta →';e.target.querySelectorAll('input,.token').forEach(el=>el.disabled=true);$('#check-btn').focus();document.querySelector('.session-heading')?.lastElementChild&&(document.querySelector('.session-heading').lastElementChild.textContent=session.correct+(session.correct===1?' correcta':' correctas')+' en esta sesión');}
function next(){session.index++;session.checked=false;orderSelection=[];$('#main').innerHTML=practice(session.topic);$('#main').focus()}
function renderOrder(){let q=session.qs[session.index];$('#answer-zone').innerHTML=orderSelection.map(i=>`<button class="token" type="button" data-action="unword" data-index="${i}">${esc(q._options[i])}</button>`).join('');document.querySelectorAll('#word-bank button').forEach(b=>b.disabled=orderSelection.includes(+b.dataset.index))}
function vocab(){let vs=D.vocab.filter(v=>(vocabGroup==='All'||v.group===vocabGroup)&&(v.term+' '+v.meaning+' '+v.example).toLowerCase().includes(search.toLowerCase()));return heading('Vocabulario · 70 expresiones','Tu colección de palabras.','Aprende cada expresión en contexto. Intenta recordar el significado antes de revelar la ficha.')+`<label for="vocab-search">Buscar una palabra, significado o ejemplo</label><input id="vocab-search" name="vocab-search" class="search-box" value="${esc(search)}" placeholder="Por ejemplo: name, hábitos, inherit…" type="search" autocomplete="off"><div class="filters">${['All',...new Set(D.vocab.map(v=>v.group))].map(g=>`<button class="chip ${vocabGroup===g?'active':''}" data-action="vocab-group" aria-pressed="${vocabGroup===g}" data-id="${g}">${g==='All'?'Todas · 70':g}</button>`).join('')}</div><p id="vocab-summary" style="font-size:12px">${vs.length} ${vs.length===1?'ficha':'fichas'} · ${state.known.length} marcadas como aprendidas. El audio, si está disponible, usa la voz sintética de tu navegador.</p><div id="vocab-cards" class="vocab-grid">${!vs.length?'<p class="empty">No encontramos esa palabra. Prueba una búsqueda más corta.</p>':''}${vs.map(v=>{let id=D.vocab.indexOf(v);return `<article class="vocab-card"><div class="vocab-card-top"><small>${v.group}</small><span class="vocab-state">${state.known.includes(id)?'✓ Aprendida':''}</span></div><h2 lang="en">${esc(v.term)}</h2>${flashOpen.has(id)?`<p>${esc(v.meaning)}</p><p class="example" lang="en">“${esc(v.example)}”</p>`:'<p class="recall-prompt">Antes de mirar, intenta usar esta expresión en una frase.</p>'}<div class="actions"><button class="tiny" data-action="flip" data-index="${id}" aria-expanded="${flashOpen.has(id)}">${flashOpen.has(id)?'Ocultar':'Ver significado'}</button><button class="tiny" data-action="speak" data-index="${id}" aria-label="Escuchar ejemplo de ${esc(v.term)}">${icon('audio')}<span>Escuchar</span></button><button class="tiny" data-action="known" aria-pressed="${state.known.includes(id)}" data-index="${id}">${state.known.includes(id)?'✓ Aprendida':'Ya la sé'}</button></div></article>`}).join('')}</div>`}
const tasks={profile:{title:'A personal profile',range:[150,200],prompt:'Write a 150–200-word profile for a class website. Include your background, interests, a specific experience or achievement, and your current goal.',checks:['Presento mi origen y contexto.','Incluyo intereses o habilidades con detalles.','Desarrollo una experiencia o logro concreto.','Explico mi objetivo actual.','El tono es cercano y adecuado a mi clase.']},object:{title:'A treasured object',range:[120,160],prompt:'Describe an object in 120–160 words: its origin, physical details, a specific memory and why it matters today. Include one continuous form and one past-habit structure.',checks:['Explico qué es y de dónde viene.','Incluyo detalles físicos concretos.','Cuento un recuerdo específico.','Explico por qué importa hoy.','Uso una forma continua y un hábito pasado.']},speaking:{title:'Speak, notice, repeat',range:[0,0],prompt:'Choose one task below. Speak aloud, then write a transcript or notes. Read it again to improve accuracy and range.',checks:['Expreso una idea, una razón y un ejemplo.','Uso las estructuras solicitadas.','Apoyo mis especulaciones en detalles observables.','Identifico una mejora y repito la intervención.']}};
function wordCount(s){return (s.trim().match(/\b[\p{L}\p{N}]+(?:[’'-][\p{L}\p{N}]+)*\b/gu)||[]).length}
function writing(){const t=tasks[writingType];return heading('Writing & speaking','Dale forma a tus ideas.','Escribe, comprueba la estructura y revisa tu borrador. Tus textos se guardan en este navegador.')+`<div class="tabs">${Object.entries(tasks).map(([k,v])=>`<button class="chip ${k===writingType?'active':''}" data-action="writing-tab" aria-pressed="${k===writingType}" data-id="${k}">${v.title}</button>`).join('')}</div><div class="writing-layout"><section class="panel"><h2 lang="en">${t.title}</h2><p lang="en">${t.prompt}</p>${writingType==='speaking'?`<div class="speaking-prompt"><b>Elige una intervención</b><ol><li>Names · 2 min: tu nombre, apodo y primeras impresiones.</li><li>Habits · 2 min: usa tend to, keep + -ing y used to / would.</li><li>Portrait · 90 s: observa un retrato propio, formula tres especulaciones y usa una expresión imprecisa.</li></ol><p>Grábate con tu dispositivo si quieres. Este espacio revisa tu transcripción; no analiza audio.</p></div>`:''}<label for="draft">${writingType==='speaking'?'Transcripción o notas':'Tu borrador en inglés'}</label><textarea id="draft" name="draft" autocomplete="off" placeholder="Start your story here…">${esc(state.drafts[writingType]||'')}</textarea><div class="actions" style="justify-content:space-between;margin:12px 0"><span class="muted" id="word-count" style="font-size:12px">${wordCount(state.drafts[writingType]||'')} palabras${t.range[1]?' · objetivo '+t.range.join('–'):''}</span><button class="btn" data-action="analyze">Revisar borrador →</button></div><div id="writing-feedback" aria-live="polite"></div></section><aside><div class="panel"><h2>Antes de darlo por listo</h2><ul class="checklist">${t.checks.map((c,i)=>`<li><label><input type="checkbox" data-check="${writingType}-${i}" ${state.checks[writingType+'-'+i]?'checked':''}>${c}</label></li>`).join('')}</ul><p style="font-size:11px">La lista es tu autoevaluación. La revisión automática detecta algunos patrones, longitud y organización; no certifica nivel C1 ni evalúa todo el significado.</p></div><div class="note"><b>Una buena revisión tiene tres pasos.</b><br>Primero el mensaje, después la gramática y por último la naturalidad. Lee tu texto en voz alta.</div><details class="panel"><summary>Ver modelos y guía</summary>${markdown(writingType==='object'?guideParts.objects():D.resources.personal.split('## Stage 3:')[1]?.split('## Stage 4:')[0]||guideParts.writing())}</details></aside></div>`}
function analyze(){let text=$('#draft').value.trim(),count=wordCount(text),t=tasks[writingType];if(!text){toast('Escribe un borrador para poder revisarlo.');return}let notes=[];if(t.range[1])notes.push(count<t.range[0]?`Añade detalles: tienes ${count} palabras; el objetivo es ${t.range.join('–')}.`:count>t.range[1]?`Recorta repeticiones: tienes ${count} palabras; el objetivo es ${t.range.join('–')}.`:`✓ Extensión dentro del objetivo: ${count} palabras.`);const paragraphs=text.split(/\n\s*\n/).filter(Boolean).length;notes.push(paragraphs<2?'Organización: separa el texto en párrafos con funciones claras.':`✓ Has separado el texto en ${paragraphs} párrafos. Revisa que cada uno desarrolle una idea.`);
const rules=[[/\b(?:am|is|are|was|were)\s+(?:knowing|owning|belonging)\b/i,'Revisa los verbos de estado: know, own y belong normalmente se usan en simple.'],[/\bprone to\s+(?:forget|make|leave|spend)\b/i,'Después de prone to usa -ing: prone to forgetting / making / leaving / spending.'],[/\bkeeps? to\b/i,'Para repetición usa keep + -ing: keep practising.'],[/\b(?:many stuffs|stuffs)\b/i,'Stuff es incontable: a lot of stuff, sin -s.'],[/\ba plenty of\b/i,'Usa plenty of, sin a.'],[/\ba couple (?!of\b)\w+/i,'Comprueba a couple of + sustantivo plural.'],[/\bexactly\b.{0,15}\b\w+-ish\b/i,'Evita combinar exactly con -ish.'],[/\bsince \d+ (?:years|months|days|hours)\b/i,'Para una duración usa for; since requiere un punto de inicio.']];let hits=rules.filter(([r])=>r.test(text));notes.push(...hits.map(([,m])=>m));if(!hits.length)notes.push('No se detectaron los errores concretos que comprueba este sistema. Aún conviene revisar el resto de la gramática.');
if(writingType==='object'){notes.push(/\b(?:used to|would)\b/i.test(text)?'✓ Se detecta una posible estructura de hábito pasado; comprueba su uso.':'Añade un hábito pasado, por ejemplo: We used to play together.');notes.push(/\b(?:am|is|are|was|were|been)\s+\w+ing\b/i.test(text)?'✓ Se detecta una posible forma continua; explica qué significado tiene.':'Incluye una forma continua relevante al contexto.');}
if(writingType==='profile')notes.push(/\b(?:goal|aim|hope|improv|learning|studying|look forward)\w*\b/i.test(text)?'Se detecta vocabulario de objetivos: verifica que expresas tu meta con claridad.':'Revisa si has explicado tu objetivo actual de manera explícita.');
$('#writing-feedback').innerHTML='<div class="feedback"><strong>Revisión orientativa · reglas locales</strong><ul>'+notes.map(n=>'<li>'+esc(n)+'</li>').join('')+'</ul><p>No se envía el texto a ningún servicio de IA. Para valorar ideas, tono y alternativas válidas, solicita una revisión a tu tutor.</p></div>'}
function review(){const ms=missed(),s=stats();return heading('Tu actividad','Cada intento te hace avanzar.','Una respuesta fallida queda pendiente hasta que la resuelvas. El porcentaje global conserva todos tus intentos.')+`<div class="results"><div><b>${s.mastered}</b><span>resueltos en el último intento</span></div><div><b>${ms.length}</b><span>errores pendientes</span></div><div><b>${s.tries}</b><span>intentos acumulados</span></div><div><b>${s.tries?s.accuracy+'%':'—'}</b><span>acierto global</span></div></div>${ms.length?`<div class="actions" style="margin-bottom:25px">${btn('Practicar mis errores','#practice/errors')}${btn('Volver a la guía','#guide',true)}</div><div class="review-list">${ms.map(q=>`<article class="review-item"><small>${D.lessons.find(l=>l.id===q.topic).subtitle}</small><h3 style="margin:8px 0">${esc(q.prompt)}</h3><p>Tu respuesta: ${esc(state.answers[q.id].last)}</p><details><summary>Ver explicación y respuesta</summary><p><strong>${esc(q.answer)}</strong></p><p>${esc(q.why)}</p></details></article>`).join('')}</div>`:`<div class="empty"><h2>${s.done?'Todo revisado. Sigue ampliando.':'Tu cuaderno de errores está listo.'}</h2><p>${s.done?'No tienes errores pendientes. Prueba otro bloque o una sesión mixta.':'Practica primero. Aquí aparecerán las preguntas que necesites reforzar, junto con su explicación.'}</p>${btn('Practicar ahora','#practice')}</div>`}<div class="note">Tu progreso pertenece a este navegador. Puedes descargar una copia y restaurarla en otro dispositivo.</div><div class="actions"><button class="btn secondary" data-action="export">Descargar progreso</button><label class="btn secondary file-import">Importar progreso<input type="file" id="import-progress" accept="application/json" aria-label="Importar progreso"></label></div>`}
function plan(){return heading('A LITTLE EVERY DAY','Una unidad. Siete días.','Dedica unos 20–30 minutos diarios. Repite los bloques que necesiten más tiempo.')+`<div class="panel"><ol class="plan">${[['Nombres y vocabulario','Explica cinco expresiones y crea ejemplos propios.'],['Aspecto continuo','Responde los ejercicios y explica cada elección.'],['Hábitos y personalidad','Describe tus hábitos durante dos minutos.'],['Especulación y lenguaje impreciso','Describe un retrato con evidencia y cautela.'],['Perfil personal','Redacta y revisa 150–200 palabras.'],['Objetos y recuerdos','Escribe 120–160 palabras sobre un objeto.'],['Recuperación y repaso','Repite tus errores sin apuntes y revisa el Lookback.']].map(([a,b])=>`<li><div><b>${a}</b><p style="margin:3px 0">${b}</p></div></li>`).join('')}</ol>${btn('Empezar por la guía','#guide')}</div>`}
function sources(resource){if(resource&&D.resources[resource])return heading('THE STUDY LIBRARY','Tu material de referencia.','Contenido del material de estudio ya disponible en este proyecto.')+`<div class="actions" style="margin-bottom:20px">${btn('Todos los recursos','#sources',true)}<button class="btn secondary" data-action="print">Imprimir</button></div><article class="reader" lang="en">${markdown(D.resources[resource])}</article>`;return heading('THE STUDY LIBRARY','Todo tu material, a mano.','Guías y respuestas del proyecto, con referencias a las páginas impresas del libro.')+`<div class="panel source-links">${[['guide','Guía de estudio completa'],['extra','Lead-in, lectura, pronunciación y material complementario'],['answers','Solucionario explicado del libro · pp. 6–17, 129 y 148'],['lookback','Lookback · repaso de la p. 18'],['practice','Práctica original · lectura, speaking y writing'],['personal','Actividad de perfil personal · modelo de Luis']].map(([k,n])=>`<a href="#sources/${k}">${n} <span aria-hidden="true">↗</span></a>`).join('')}<a href="My_Godmothers_Mandolin.pdf" target="_blank" rel="noopener">Actividad: My Godmother’s Mandolin ↗</a><a href="Unit_1_Follow_Up_Activity.pdf" target="_blank" rel="noopener">Actividad de seguimiento de la unidad 1 ↗</a><a href="unit-1-study-pack.pdf" target="_blank" rel="noopener">Descargar guía y práctica en PDF ↗</a><a href="unit-1-textbook-answer-key.pdf" target="_blank" rel="noopener">Descargar solucionario en PDF ↗</a><a href="unit-1-lookback-answer-key.pdf" target="_blank" rel="noopener">Descargar Lookback en PDF ↗</a></div><div class="note"><b>Alcance y fuentes.</b> Basado en el PDF de la unidad 1, nivel XI C1 (16 páginas escaneadas), la guía, prácticas y solucionarios del proyecto; más el suplemento de la unidad 2 con las páginas 18 y 158. Los ejercicios interactivos son práctica adaptada y original.<br><br><b>Audio y vídeo pendientes.</b> No están disponibles las grabaciones oficiales ni el vídeo. El sitio no asigna respuestas a tareas que requieren escucharlos. La lectura y el vocabulario de Francesco’s Venice sí se pueden estudiar. Los perfiles de personalidad se usan para discusión, no para diagnosticar a una persona.</div>`}
function render(){const [rawPage,id]=location.hash.slice(1).split('/');const page=rawPage||'home';if(page!=='practice')session=null;if(page==='writing'&&tasks[id])writingType=id;const names={home:'Inicio',guide:'Guía de estudio',practice:'Práctica',vocab:'Vocabulario',writing:'Writing & speaking',review:'Mi repaso',sources:'Biblioteca',plan:'Plan de estudio'};const title=document.querySelector('#current-page');if(title)title.textContent=names[page]||'Inicio';document.body.dataset.page=page||'home';document.querySelector('[data-action=open-menu]')?.classList.toggle('active',['writing','review','sources','plan'].includes(page));document.querySelectorAll('[data-nav]').forEach(a=>{let active=a.dataset.nav===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#main').innerHTML=page==='guide'?guide(id):page==='practice'?practice(id||'all'):page==='vocab'?vocab():page==='writing'?writing():page==='review'?review():page==='plan'?plan():page==='sources'?sources(id):home();save();window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>{const d=document.querySelector('#navigation-dialog');if(d?.open)d.close();render();$('#main').focus()});
document.addEventListener('submit',e=>{if(e.target.id==='exercise-form')check(e)});
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,i=+b.dataset.index;
if(a==='open-menu'){document.querySelector('#navigation-dialog').showModal();b.setAttribute('aria-expanded','true');return}if(a==='close-menu'){document.querySelector('#navigation-dialog').close();return}
if(a==='read'){state.read=state.read.includes(id)?state.read.filter(x=>x!==id):[...state.read,id];save();const scrollPosition=window.scrollY;render();window.scrollTo(0,scrollPosition);document.querySelector('[data-action=read]')?.focus({preventScroll:true});toast(state.read.includes(id)?'Bloque marcado como estudiado.':'Bloque pendiente de estudio.');}
if(a==='restart'){startSession($('#topic')?.value||session?.topic||'all',$('#exercise-type')?.value||session?.type||'all');$('#main').innerHTML=practice(session.topic)}
if(a==='hint'){if(session.checked)return;const q=session.qs[session.index];$('#feedback').innerHTML=`<div class="note"><b>Pista</b><p>${q.type==='error'?'Busca un problema de estructura, preposición o forma verbal.':q.type==='order'?'Busca primero el sujeto, después el auxiliar y el verbo.':q.type==='gap'?'Piensa en la colocación o patrón completo.':'Compara el contexto y el significado, además de la forma.'} ${q.type==='gap'?'La respuesta tiene '+String(q.answer).split(' ').length+' palabra(s).':''}</p><a href="#guide/${q.topic}">Consultar la teoría de este bloque →</a></div>`;}
if(a==='solution'){if(session.checked)return;const q=session.qs[session.index];const old=state.answers[q.id]||{attempts:0,correctAttempts:0};state.answers[q.id]={...old,correct:false,attempts:old.attempts+1,last:'Solución consultada'};save();session.checked=true;document.querySelectorAll('[data-action=hint],[data-action=solution]').forEach(b=>b.disabled=true);$('#feedback').innerHTML=`<div class="feedback wrong"><strong>Solución consultada · queda para repasar</strong><p lang="en">${esc(q.answer)}</p><p>${esc(q.why)}</p></div>`;$('#check-btn').textContent='Siguiente pregunta →';$('#exercise-form').querySelectorAll('input,.token').forEach(el=>el.disabled=true);}
if(a==='word'&&!session.checked){orderSelection.push(i);renderOrder()}if(a==='unword'&&!session.checked){orderSelection=orderSelection.filter(v=>v!==i);renderOrder()}
if(a==='vocab-group'){vocabGroup=id;$('#main').innerHTML=vocab()}if(a==='flip'){flashOpen.has(i)?flashOpen.delete(i):flashOpen.add(i);$('#main').innerHTML=vocab();document.querySelector('[data-action=flip][data-index="'+i+'"]')?.focus({preventScroll:true})}
if(a==='known'){state.known=state.known.includes(i)?state.known.filter(v=>v!==i):[...state.known,i];save();$('#main').innerHTML=vocab();document.querySelector('[data-action=known][data-index="'+i+'"]')?.focus({preventScroll:true})}
if(a==='speak'){if(!('speechSynthesis'in window)){toast('Tu navegador no ofrece síntesis de voz. Lee el ejemplo en voz alta.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(D.vocab[i].example);u.lang='en-GB';u.rate=.85;u.onerror=()=>toast('No hay voz disponible. Puedes leer el ejemplo en la ficha.');speechSynthesis.speak(u)}
if(a==='writing-tab'){writingType=id;location.hash='writing/'+id;$('#main').innerHTML=writing()}if(a==='analyze')analyze();if(a==='print')window.print();
if(a==='export'){const blob=new Blob([JSON.stringify({version:1,state},null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='english-studio-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Copia de progreso descargada.');}
});
document.addEventListener('change',async e=>{if(e.target.id==='lesson-picker'){location.hash='guide/'+e.target.value;return}if(['topic','exercise-type'].includes(e.target.id)){const topic=$('#topic').value,type=$('#exercise-type').value;startSession(topic,type);if(location.hash!=='#practice/'+topic)location.hash='practice/'+topic;else $('#main').innerHTML=practice(topic)}if(e.target.dataset.check){state.checks[e.target.dataset.check]=e.target.checked;save()}if(e.target.id==='import-progress'){try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error();const p=JSON.parse(await f.text());if(p.version!==1||!p.state||!p.state.answers||!Array.isArray(p.state.read)||!Array.isArray(p.state.known))throw Error();if(!window.confirm('¿Reemplazar el progreso actual por esta copia?'))return;state={answers:p.state.answers,read:p.state.read.filter(x=>D.lessons.some(l=>l.id===x)),known:p.state.known.filter(x=>Number.isInteger(x)&&x>=0&&x<D.vocab.length),drafts:p.state.drafts||{},checks:p.state.checks||{}};save();session=null;render();toast('Progreso restaurado.')}catch{toast('No se pudo importar. Elige una copia JSON de English Studio.')}}});
document.addEventListener('input',e=>{if(e.target.id==='draft'){state.drafts[writingType]=e.target.value;save();$('#word-count').textContent=wordCount(e.target.value)+' palabras'+(tasks[writingType].range[1]?' · objetivo '+tasks[writingType].range.join('–'):'')}if(e.target.id==='vocab-search'){search=e.target.value;const tmp=document.createElement('div');tmp.innerHTML=vocab();$('#vocab-cards').innerHTML=tmp.querySelector('#vocab-cards').innerHTML||'<p class="empty">No encontramos esa palabra. Prueba una búsqueda más corta.</p>';$('#vocab-summary').textContent=tmp.querySelector('#vocab-summary').textContent;}});
document.querySelector('#navigation-dialog')?.addEventListener?.('close',()=>document.querySelector('[data-action=open-menu]')?.setAttribute('aria-expanded','false'));
window.EnglishStudio={normalize,judge,wordCount,stats};render();
